 const desktop=figma.root.children.find(p=>p.name.startsWith('01 ·'));if(desktop){await desktop.loadAsync();legacy=desktop.children.filter(n=>n.type==='FRAME'&&legacyNames.has(n.name)).map(n=>({id:n.id,name:n.name}));}
 for(const page of figma.root.children){if(!page.name.startsWith('01 ·')&&!page.name.startsWith('02 ·'))continue;await page.loadAsync();for(const section of page.children){if(section.type!=='SECTION')continue;for(const root of section.children){if(root.type!=='FRAME')continue;roots.push(root);const nodes=root.findAll(()=>true),images=[];for(const n of nodes){counts[n.type]=(counts[n.type]||0)+1;if(n.type==='TEXT'){for(const s of n.getStyledTextSegments(['fontName']))fonts.add(s.fontName.family);}if(Array.isArray(n.fills)&&n.fills.some(f=>f.type==='IMAGE'))images.push({name:n.name,w:n.width,h:n.height});}rows.push({id:root.id,name:root.name,w:root.width,h:root.height,texts:nodes.filter(n=>n.type==='TEXT').length,images});}}}
 const report={screens:roots.length,counts,fonts:[...fonts],legacy:legacy.length,map:rows.filter(r=>r.name.includes('/app/map')&&r.name.includes('Карта')),rows};
 figma.ui.postMessage({type:'report',report});
