async function repairLayout(){const styles={Inter:{400:'Regular',500:'Medium',600:'Semi Bold',700:'Bold',800:'Bold',900:'Bold'},Manrope:{400:'Bold',500:'Bold',600:'Bold',700:'Bold',800:'ExtraBold'},Cousine:{400:'Regular',700:'Bold'}};const fonts=new Map();for(const root of roots)for(const n of root.findAllWithCriteria({types:['TEXT']}))for(const s of n.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(s.fontName),s.fontName);for(const family of Object.keys(styles))for(const style of new Set(Object.values(styles[family])))fonts.set(family+'|'+style,{family,style});for(const font of fonts.values())await figma.loadFontAsync(font);let changed=0;function fix(n,d,isRoot=false){if(n.type==='INSTANCE'||d.k==='svg')return;if(n.type==='TEXT'&&d.k==='text'){const family=d.font||'Inter',weight=Math.min(family==='Manrope'?800:900,Math.max(400,Math.round(d.weight/100)*100));n.fontName={family,style:styles[family]?.[weight]||'Regular'};n.textAlignHorizontal=d.align==='center'?'CENTER':d.align==='right'||d.align==='end'?'RIGHT':'LEFT';if(d.h<d.line*1.4){n.textAutoResize='WIDTH_AND_HEIGHT';n.x=d.x+(d.w-n.width)*(d.align==='center'?.5:d.align==='right'||d.align==='end'?1:0);n.y=d.y-(d.line-d.h)/2;}else{n.textAutoResize='HEIGHT';n.resize(Math.max(1,d.w),Math.max(1,d.h));n.x=d.x;n.y=d.y;}changed++;return;}if(n.type==='FRAME'){n.resize(Math.max(1,d.w),Math.max(1,d.h));if(!isRoot){n.x=d.x;n.y=d.y;}const children=[...n.children];for(let i=0;i<(d.children||[]).length&&i<children.length;i++)fix(children[i],d.children[i]);changed++;}}for(const root of roots){const data=layoutMap[root.name+'|'+Math.round(root.width)];if(data)fix(root,data,true);}figma.ui.postMessage({type:'repaired',count:changed});}
